import json
import sys

data = json.load(sys.stdin)

# Check for tables related to exchange rates or foreign currency
def search_for_exchange(obj, depth=0):
    if depth > 8:
        return []
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, str) and 'exchange' in v.lower():
                results.append(f'Key: {k}, Value: {v[:200]}')
            results.extend(search_for_exchange(v, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(search_for_exchange(item, depth+1))
    return results

results = search_for_exchange(data)
for r in results[:5]:
    print(r)
